import {PRESETS,RISK_SOURCE,eventExposure,stressCases,annualExposure,validateRisk} from './risk-model.js';
const moneyFormatter=new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',maximumFractionDigits:0}),numberFormatter=new Intl.NumberFormat('en-AU',{maximumFractionDigits:1});
const money=n=>moneyFormatter.format(n),fmt=n=>numberFormatter.format(n);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cachedKey='',cachedResult;
function annual(a){const key=JSON.stringify(a);if(cachedKey!==key){cachedResult=annualExposure(a);cachedKey=key}return cachedResult}
const pair=(label,left,right,max)=>`<div class="riskbarrow"><b>${label}</b><div><div class="riskbarline"><div class="riskbar before" style="width:${max?left/max*100:0}%"></div><span>${money(left)}</span></div><div class="riskbarline"><div class="riskbar after" style="width:${max?right/max*100:0}%"></div><span>${money(right)}</span></div></div></div>`;
function legend(){return '<div class="risklegend"><span><i class="before"></i> No cost share</span><span><i class="after"></i> Proposed cost share</span></div>'}
function source(){return `<details class="riskmethod"><summary>Source, adaptation & limitations</summary><p>Structure adapted from <b>${RISK_SOURCE.file}</b>: Demo A5:C20 (one event), Assumptions A19:C22 (notice bands), Scenarios A4:F17 (stress tests) and Results A4:D15 (annual risk chart).</p><p>All bakery prices, recovery fractions, handling/disposal costs and volumes are illustrative editable inputs, not measured bakery data. Preset order and affected volumes follow this prototype’s seed plans; the financial scenario stays separate from live operational records.</p><p>The source’s 80% / 50% / 0% shares are proposed policy assumptions. Flour uses its 2 / 8-day boundaries; bread and pastry use illustrative 1 / 3-day boundaries for this demo. The source’s 15% weekly change probability and 30% variability are assumptions, not bakery evidence.</p><p>The original tomato simulation uses fixed draws generated at workbook creation. This version regenerates 10,000 reproducible 52-week trials from the selected inputs. Independent weekly changes have the chosen probability, event exposure is lognormal with the selected coefficient of variation, and the selected notice/share applies to every event. It does not reproduce the original Beta cancellation or weather model.</p><p>Tomato prices, crop-loss statistics and grower volumes are excluded. Weather-pool premiums and ruin estimates are also excluded: bakery risk frequency, cross-business dependence, reserve rules and coverage would need their own evidence. No emissions or people-served estimates are inferred from this financial scenario.</p></details>`}
export function riskSummary(a){const r=annual(a);return `<section class="panel risksection" id="risk-overview"><div class="sectionhead"><div><span class="eyebrow">ILLUSTRATIVE SCENARIO · NOT REPORTED OUTCOMES</span><h2>Late-order risk: an annual view</h2></div><button data-action="risk-open" class="primary">Explore assumptions</button></div><p>${escape(a.label)} · ${fmt(a.cancelled)} kg affected per base event · ${fmt(a.notice)} days’ notice. This standalone model is independent of the dashboard’s state, period and category filters.</p><div class="riskgrid"><div>${legend()}${pair('Average year',r.baseline.mean,r.shared.mean,r.baseline.tvar95)}${pair('95th percentile',r.baseline.var95,r.shared.var95,r.baseline.tvar95)}${pair('Average worst 5%',r.baseline.tvar95,r.shared.tvar95,r.baseline.tvar95)}</div><div class="riskexplanation"><h3>Who carries the exposure?</h3><p>The selling business’s modelled average annual exposure changes from <b>${money(r.baseline.mean)}</b> to <b>${money(r.shared.mean)}</b>.</p><p>The ordering business takes on <b>${money(r.buyer.mean)}</b> on average. Combined exposure is unchanged by sharing alone.</p><small>95th percentile: 95% of simulated annual costs are at or below this level. Average worst 5%: mean of the 500 highest simulated costs. These are model outputs, not predicted real-world frequencies.</small></div></div></section>`}
const fields=[['order','Weekly order (kg)',1,1],['cancelled','Affected produced volume (kg)',0,1],['price','Contract price (A$/kg)',0.01,.01],['salvage','Recovery sale price (A$/kg)',0,.01],['recovery','Share recovered (%)',0,1,100],['disposal','Residual disposal cost (A$/kg)',0,.01],['handling','Recovery handling cost (A$/kg)',0,.01],['notice','Notice before delivery (days)',0,.5]];
const policyFields=[['shortDays','Short-notice boundary (days)',0,.5],['longDays','Long-notice boundary (days)',.5,.5],['shortShare','Ordering party share: short notice (%)',0,1,100],['mediumShare','Ordering party share: middle band (%)',0,1,100],['longShare','Ordering party share: long notice (%)',0,1,100],['frequency','Weekly chance of an order change (%)',0,1,100],['severityCV','Event exposure variation (CV %)',0,1,200]];
function controls(list,a){return list.map(([id,label,min,step,max])=>`<div class="field"><label for="risk-${id}">${label}</label><input id="risk-${id}" name="${id}" type="number" required min="${min}" ${max!==undefined?`max="${max}"`:''} step="${step}" value="${a[id]}"></div>`).join('')}
export function riskBusiness(a){const e=eventExposure(a),scenarios=stressCases(a),max=Math.max(...scenarios.map(c=>c.result.total),1);return `<section class="panel risksection" id="risk-analysis"><div class="sectionhead"><div><span class="eyebrow">BAKERY COST-SHARING LAB</span><h2>What does a late order change cost?</h2></div><span class="badge amber">Editable demo assumptions</span></div><p>Explore one handover at a time. “Selling business” and “ordering business” replace the tomato model’s grower and retailer.</p><form id="risk-form"><label for="risk-preset">Illustrative handover</label><select id="risk-preset">${Object.entries(PRESETS).map(([id,p])=>`<option value="${id}" ${a.preset===id?'selected':''}>${escape(p.label)}</option>`).join('')}</select><p class="footnote">Choosing a preset replaces the scenario inputs below. It does not change business plans or recorded outcomes.</p><div class="formgrid riskinputs">${controls(fields,a)}</div><details class="riskpolicy"><summary>Proposed policy bands & annual simulation assumptions</summary><div class="formgrid">${controls(policyFields,a)}</div></details><p class="formerror" id="risk-error" role="alert"></p><button class="primary" type="submit">Recalculate scenario & charts</button><span class="riskhint">Charts show the last calculated inputs until you apply changes.</span></form><div class="riskdivider"></div><div class="stats three"><article class="stat"><span>Affected order share</span><strong>${fmt(a.cancelled/a.order*100)}%</strong><small>${fmt(a.cancelled)} of ${fmt(a.order)} kg · not a measured waste rate</small></article><article class="stat"><span>Estimated exposure per event</span><strong>${money(e.total)}</strong><small>Revenue shortfall + handling and disposal costs</small></article><article class="stat green"><span>Ordering party’s proposed share</span><strong>${fmt(e.buyerRate*100)}%</strong><small>Based on ${fmt(a.notice)} days’ notice</small></article></div><div class="riskgrid"><div><h3>Who pays for one late change?</h3>${legend()}${pair(escape(a.seller)+' (seller)',e.total,e.seller,Math.max(e.total,1))}${pair(escape(a.buyer)+' (orderer)',0,e.buyer,Math.max(e.total,1))}<p class="footnote">Together: ${money(e.total)} under either arrangement. A transfer is not a net saving.</p></div><div><h3>Trace the calculation</h3><dl class="riskledger"><div><dt>Affected contract value</dt><dd>${money(e.contractValue)}</dd></div><div><dt>Less recovery sales</dt><dd>−${money(e.recoveredRevenue)}</dd></div><div><dt>Recovery handling</dt><dd>+${money(e.handlingCost)}</dd></div><div><dt>Residual disposal</dt><dd>+${money(e.disposalCost)}</dd></div><div><dt>Estimated exposure (floored at zero)</dt><dd>${money(e.total)}</dd></div></dl><p class="footnote">${fmt(e.recovered)} kg assumed recovered; ${fmt(e.residual)} kg residual. No real recovery is recorded. This is not accounting profit: production costs, avoided costs, taxes and margin are outside the model.</p></div></div><h3 class="riskstresstitle">Five bakery stress tests</h3><p>Change the assumptions above to recalculate every case. Notice alone does not change physical loss.</p>${legend()}<div class="riskstress">${scenarios.map(c=>pair(c.name,c.result.total,c.result.seller,max)).join('')}</div><details><summary>Detailed scenario data</summary><div class="tablewrap"><table><thead><tr><th>Scenario</th><th>Affected kg</th><th>Notice days</th><th>Recovered %</th><th>Total exposure</th><th>Seller pays</th><th>Ordering party pays</th></tr></thead><tbody>${scenarios.map(c=>`<tr><td><b>${c.name}</b><small>${c.note}</small></td><td>${fmt(c.inputs.cancelled)}</td><td>${fmt(c.inputs.notice)}</td><td>${fmt(c.inputs.recovery)}%</td><td>${money(c.result.total)}</td><td>${money(c.result.seller)}</td><td>${money(c.result.buyer)}</td></tr>`).join('')}</tbody></table></div></details><div class="tip"><span>i</span><div><b>Earlier notice + better recovery is a two-input scenario.</b> It assumes a higher recovery share as well as more notice. Lower payment responsibility does not establish food waste prevention.</div></div><button data-action="risk-export">Download scenario data</button>${source()}</section>`}
export function riskPolicy(a){const e=eventExposure(a);return `<section class="panel risksection"><div class="sectionhead"><div><span class="eyebrow">PROPOSED INCENTIVE MECHANISM</span><h2>Share the cost of late changes</h2></div><button data-action="risk-open">Test policy assumptions</button></div><p>Illustrative ${escape(a.label.toLowerCase())} arrangement. A working group would need to agree eligibility, evidence and funding before this could become a program rule.</p><div class="tablewrap"><table><thead><tr><th>Notice window</th><th>Ordering party contributes</th><th>Selling party retains</th></tr></thead><tbody>${[[`Less than ${fmt(a.shortDays)} days`,a.shortShare],[`${fmt(a.shortDays)} to less than ${fmt(a.longDays)} days`,a.mediumShare],[`${fmt(a.longDays)} days or more`,a.longShare]].map(([label,share])=>`<tr><td>${label}</td><td>${fmt(share)}%</td><td>${fmt(100-share)}%</td></tr>`).join('')}</tbody></table></div><p class="footnote">Current scenario: the ordering business contributes ${money(e.buyer)} and the selling business retains ${money(e.seller)}. EFWA coordinates the rule; it is not assumed to pay either amount.</p><details class="riskmethod"><summary>Why the tomato weather pool is not copied</summary><p>The supplied workbook prices a crop-weather pool using assumed frequency, severity and membership. Bakery spoilage, process disruption and grain-weather risk are different exposures. Coverage, correlated claims, reserves and funding require separate data. A positive safety loading alone does not establish that a pool is adequately funded.</p></details></section>`}
export function bindRisk(state,save,render){const form=document.querySelector('#risk-form');if(!form)return;document.querySelector('#risk-preset').addEventListener('change',e=>{state.risk={...PRESETS[e.target.value],preset:e.target.value};save();render();document.querySelector('#risk-analysis')?.scrollIntoView({block:'start'})});form.addEventListener('submit',e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(form)),next={...state.risk};for(const [key] of [...fields,...policyFields])next[key]=Number(data[key]);validateRisk(next);state.risk=next;save();render();document.querySelector('#risk-analysis')?.scrollIntoView({block:'start'})}catch(error){document.querySelector('#risk-error').textContent=error.message}})}
export function riskCSV(a){const annualData=annual(a),rows=[['Bakery model — illustrative assumptions, AUD'],['Handover',a.label],['Source structure',RISK_SOURCE.file],[],['Input','Value'],...[...fields,...policyFields].map(([key,label])=>[label,a[key]]),[],['Scenario','Affected kg','Notice days','Recovered percent','Total exposure AUD','Seller pays AUD','Ordering party pays AUD'],...stressCases(a).map(c=>[c.name,c.inputs.cancelled,c.inputs.notice,c.inputs.recovery,c.result.total,c.result.seller,c.result.buyer]),[],['Annual simulation','Mean AUD','95th percentile AUD','Average worst 5 percent AUD'],['Seller without sharing',annualData.baseline.mean,annualData.baseline.var95,annualData.baseline.tvar95],['Seller with sharing',annualData.shared.mean,annualData.shared.var95,annualData.shared.tvar95],['Ordering party with sharing',annualData.buyer.mean,annualData.buyer.var95,annualData.buyer.tvar95],['Trials',annualData.n],['Seed',annualData.seed],['Method','52 independent weekly Bernoulli changes; lognormal event exposure; fixed selected cost share; no weather pool.'],['Limitations','Illustrative revenue-shortfall proxy, not accounting profit, verified savings or operational outcomes.']];return rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(',')).join('\r\n')}
